const plans={web:[{id:'landing',name:'Landing Khởi Động',desc:'Một trang đích, tập trung vào điều quan trọng nhất.',price:2900000,features:['1 landing page, tối đa 7 section','1 biểu mẫu nhận liên hệ','Hiển thị tốt trên điện thoại','2 vòng chỉnh sửa trong phạm vi','Hướng dẫn sử dụng khi bàn giao']},{id:'basic',name:'Website Cơ Bản',desc:'Một diện mạo chuyên nghiệp cho doanh nghiệp nhỏ.',price:5900000,featured:true,features:['Tối đa 5 trang nội dung','Quản trị nội dung cơ bản','Form liên hệ & liên kết mạng xã hội','Cấu hình SEO cơ bản','2 vòng sửa & hướng dẫn bàn giao']},{id:'growth',name:'Website Phát Triển',desc:'Thêm không gian cho nội dung và kế hoạch dài hạn.',price:9900000,features:['Tối đa 10 trang nội dung','Chuyên mục blog / kiến thức','Quản trị nội dung cơ bản','Cấu trúc sẵn sàng mở rộng','2 vòng sửa & hướng dẫn bàn giao']}],seo:[{id:'audit',name:'SEO Audit',desc:'Hiểu hiện trạng và biết việc gì nên ưu tiên.',price:1500000,features:['Khảo sát cấu trúc website','Kiểm tra kỹ thuật và metadata','Danh sách vấn đề có mức ưu tiên','Đề xuất hướng khắc phục','Chốt số URL trong báo giá']},{id:'seo',name:'SEO Định Kỳ',desc:'Một kế hoạch phù hợp với hiện trạng và nguồn lực.',price:null,featured:true,features:['Khảo sát trước khi đề xuất','Kế hoạch đầu việc theo tháng','Tối ưu kỹ thuật và nội dung','Đo lường theo nguồn dữ liệu','Báo cáo và điều chỉnh theo kỳ']},{id:'maintenance',name:'Chăm Sóc Website',desc:'Giữ website được cập nhật và có người theo dõi.',price:490000,monthly:true,features:['Kiểm tra biểu mẫu liên hệ','Cập nhật nội dung theo hạn mức','Hỗ trợ vận hành website','Lịch sao lưu theo thỏa thuận','Phát sinh được báo giá trước']}]};
const all=Object.values(plans).flat(),$=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('vi-VN').format(n)+'đ';let category='web';
function renderPlans(){ $('#plans').innerHTML=plans[category].map((p,i)=>`<article class="plan ${p.featured?'featured':''}">${p.featured?'<span class="recommended">'+(category==='web'?'GỢI Ý KHỞI ĐẦU':'THEO NHU CẦU')+'</span>':''}<span class="plan-index">GÓI 0${i+1} / ${category==='web'?'WEBSITE':'DỊCH VỤ'}</span><h3>${p.name}</h3><p class="desc">${p.desc}</p><p class="from">${p.price?'Chi phí từ':'Khảo sát & tư vấn'}</p><div class="price ${p.price?'':'quote-only'}">${p.price?new Intl.NumberFormat('vi-VN').format(p.price)+'<small>đ</small>':'Báo giá riêng'}</div><p class="billing">${p.monthly?'/ tháng':p.price?'/ gói · theo phạm vi':'Theo hiện trạng website'}</p><ul>${p.features.map(f=>'<li>'+f+'</li>').join('')}</ul><a href="#uoc-tinh" class="button" data-select="${p.id}">Chọn gói này <span>↗</span></a></article>`).join('');$('#plans').setAttribute('aria-labelledby','tab-'+category);}
$('#package').innerHTML=all.map(p=>`<option value="${p.id}">${p.name}${p.price?' — từ '+money(p.price):' — báo giá riêng'}</option>`).join('');$('#package').value='basic';
function current(){return all.find(p=>p.id===$('#package').value)}
function estimate(){const p=current(),web=plans.web.includes(p);let lines=[],upfront=p.monthly?0:p.price,recurring=p.monthly?p.price:0;lines.push([p.name,p.price?money(p.price)+(p.monthly?' / tháng':''):'Theo khảo sát']);if(web){const raw=Number($('#pages').value),pages=Number.isFinite(raw)?Math.min(20,Math.max(0,Math.trunc(raw))):0;$('#pages').value=pages;if(pages){upfront+=pages*500000;lines.push([pages+' trang bổ sung',money(pages*500000)])}if($('#copywriting').checked){upfront+=1500000;lines.push(['Biên tập nội dung',money(1500000)])}if($('#language').checked){upfront+=2000000;lines.push(['Cấu hình thêm ngôn ngữ',money(2000000)])}}if($('#care').checked&&p.id!=='maintenance'){recurring+=490000;lines.push(['Chăm sóc website',money(490000)+' / tháng'])}return {p,web,lines,upfront,recurring};}
function update(){const e=estimate();$('#extras').hidden=!e.web;$('#care').closest('label').hidden=e.p.id==='maintenance';$('#chosen-name').textContent=e.p.name;$('#summary-lines').replaceChildren(...e.lines.map(([label,value])=>{const row=document.createElement('div');row.className='summary-line';const a=document.createElement('span'),b=document.createElement('span');a.textContent=label;b.textContent=value;row.append(a,b);return row}));$('#total').textContent=e.upfront===null?'Cần khảo sát':money(e.upfront);$('#recurring').textContent=e.recurring?'Duy trì từ '+money(e.recurring)+' / tháng':'Chưa chọn dịch vụ định kỳ';$('#form-selection').textContent='Đang chọn: '+e.p.name+' · '+(e.upfront===null?'Báo giá sau khảo sát':money(e.upfront))+(e.recurring?' + '+money(e.recurring)+'/tháng':'');$('#form-status').textContent='';}
function summary(){const e=estimate();return 'WEBGỌN — BẢN ƯỚC TÍNH THAM KHẢO\nNgày: '+new Date().toLocaleDateString('vi-VN')+'\n\n'+e.lines.map(l=>l.join(': ')).join('\n')+'\n\nChi phí ban đầu: '+(e.upfront===null?'Cần khảo sát':money(e.upfront))+'\nDịch vụ định kỳ: '+(e.recurring?money(e.recurring)+'/tháng':'Chưa chọn')+'\n\nGiá tham khảo, chưa bao gồm thuế, tên miền, hosting và bản quyền bên thứ ba. Chi phí cuối cùng, đầu việc và tiến độ được xác nhận trong báo giá chính thức.\nKhông phát sinh thanh toán hoặc gửi dữ liệu từ trang này.';}
function download(text,name){const u=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.addEventListener('click',ev=>{const a=ev.target.closest('[data-select]');if(a){$('#package').value=a.dataset.select;update()}});
document.querySelectorAll('[data-category]').forEach((b,i,buttons)=>{b.addEventListener('click',()=>{category=b.dataset.category;buttons.forEach(x=>{const on=x===b;x.setAttribute('aria-selected',on);x.tabIndex=on?0:-1});renderPlans()});b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[index].focus();buttons[index].click()}})});
['package','pages','copywriting','language','care'].forEach(id=>$('#'+id).addEventListener('input',update));
$('#theme').addEventListener('click',()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('wg-theme',t)}catch{}$('#theme').setAttribute('aria-label',t==='dark'?'Chuyển sang giao diện sáng':'Chuyển sang giao diện tối')});
$('#download-quote').addEventListener('click',()=>download(summary(),'webgon-uoc-tinh.txt'));
function requestText(){const f=$('#request-form');if(!f.reportValidity())return null;const d=new FormData(f);return summary()+'\n\nTHÔNG TIN YÊU CẦU\nHọ tên: '+d.get('name').trim()+'\nEmail: '+d.get('email').trim()+'\nĐiện thoại: '+(d.get('phone').trim()||'Chưa cung cấp')+'\nNhu cầu: '+d.get('message').trim()+'\nTư vấn tích hợp AI: '+(d.get('aiInterest')?'Có — báo giá riêng':'Chưa chọn')+'\nTư vấn đào tạo Agentic & Vibe Coding: '+(d.get('trainingInterest')?'Có — xác nhận lộ trình và học phí riêng':'Chưa chọn')}
$('#request-form').addEventListener('submit',e=>{e.preventDefault();const text=requestText();if(text){download(text,'webgon-yeu-cau-bao-gia.txt');$('#form-status').textContent='Đã tạo tệp yêu cầu để bạn lưu và chia sẻ. Thông tin chưa được gửi đến WebGọn.'}});
$('#copy-request').addEventListener('click',async()=>{const text=requestText();if(!text)return;try{await navigator.clipboard.writeText(text);$('#form-status').textContent='Đã sao chép yêu cầu. Bạn có thể dán vào kênh liên hệ của mình.'}catch{$('#form-status').textContent='Trình duyệt không cho sao chép. Hãy dùng nút Tạo & tải yêu cầu.'}});
$('#year').textContent=new Date().getFullYear();renderPlans();update();

// Progressive motion: content remains visible when animation APIs are unavailable.
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
let revealObserver;
function revealContent(){
  if(motionPreference.matches||!('IntersectionObserver' in window))return;
  if(!revealObserver)revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}})},{threshold:.08});
  document.querySelectorAll('.section-top,.plan,.included-head,.included-grid article,.process li,.faq>div,.contact-intro,#request-form,.ai-demo,.ai-options article,.training-intro,.training-modules article,.training-bottom').forEach((node,index)=>{if(node.classList.contains('reveal-ready'))return;node.style.setProperty('--reveal-delay',Math.min(index%3*75,150)+'ms');node.classList.add('reveal-ready');revealObserver.observe(node)});
}
revealContent();
document.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',revealContent));
motionPreference.addEventListener('change',()=>{if(motionPreference.matches){revealObserver?.disconnect();document.querySelectorAll('.reveal-ready').forEach(node=>node.classList.add('is-visible'))}else revealContent()});
['package','pages','copywriting','language','care'].forEach(id=>$('#'+id).addEventListener('input',()=>{if(motionPreference.matches)return;$('#total').classList.remove('total-pop');void $('#total').offsetWidth;$('#total').classList.add('total-pop')}));

$('#ai-interest').addEventListener('click',()=>{$('#ai-interest-check').checked=true;});

$('#training-interest').addEventListener('click',()=>{$('#training-interest-check').checked=true;});
